/* HEXA BATTLEGROUNDS setup — PART 20 OF 20. Run parts in order. Safe to re-run. */ create or replace function host_generate_teams(p_token text, p_count int) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_start int; v_out jsonb := '[]'::jsonb; i int; v_pin text; v_salt text; v_arena uuid; v_size int; v_team teams; begin v_ev := _auth_host(p_token); if p_count < 1 or p_count > 120 then raise exception 'BAD_COUNT'; end if; v_size := _cfg(v_ev, 'arena_size'); select coalesce(max(number), 0) into v_start from teams where event_id = v_ev; for i in 1..p_count loop v_pin := _new_pin(_cfg(v_ev, 'pin_length')); v_salt := _new_token(); select a.id into v_arena from arenas a where a.event_id = v_ev and a.phase = 'lobby' and (select count(*) from teams t where t.arena_id = a.id) < v_size order by a.number limit 1; if v_arena is null then raise exception 'ALL_MAPS_FULL'; end if; insert into teams(event_id, arena_id, number, name, pin_salt, pin_hash) values (v_ev, v_arena, v_start + i, null, v_salt, _hash(v_salt || v_pin)) returning * into v_team; perform _add_item(v_team.id, 'pistol', 1); perform _add_item(v_team.id, 'medkit', 1); v_out := v_out || jsonb_build_object('number', v_team.number, 'name', v_team.name, 'pin', v_pin, 'bus', v_team.bus, 'map', (select number from arenas where id = v_arena)); end loop; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'generate_teams', jsonb_build_object('count', p_count)); return v_out; end $$; create or replace function host_import_teams(p_token text, p_teams jsonb) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; r jsonb; v_salt text; v_arena uuid; v_size int; v_n int := 0; v_team teams; v_row int := 0; v_seen int[] := '{}'; v_num int; v_pin text; v_out jsonb := '[]'::jsonb; v_generated boolean; begin v_ev := _auth_host(p_token); v_size := _cfg(v_ev, 'arena_size'); if jsonb_typeof(p_teams) <> 'array' or jsonb_array_length(p_teams) = 0 then raise exception 'BAD_ROW: the file has no squads'; end if; if jsonb_array_length(p_teams) > 120 then raise exception 'BAD_ROW: at most 120 squads per import'; end if; for r in select * from jsonb_array_elements(p_teams) loop v_row := v_row + 1; if coalesce(r ->> 'number', '') !~ '^[0-9]{1,3}$' or (r ->> 'number')::int < 1 then raise exception 'BAD_ROW: row % — squad number must be 1–999', v_row; end if; v_num := (r ->> 'number')::int; if v_num = any(v_seen) then raise exception 'BAD_ROW: row % — squad % appears twice', v_row, v_num; end if; v_seen := v_seen || v_num; if coalesce(r ->> 'pin', '') <> '' and _weak_pin(r ->> 'pin') then raise exception 'BAD_ROW: row % — PIN for squad % must be 4–8 digits and not a repeated or sequential pattern', v_row, v_num; end if; if coalesce(r ->> 'map', '') <> '' and not exists (select 1 from arenas where event_id = v_ev and number::text = r ->> 'map') then raise exception 'BAD_ROW: row % — map % does not exist', v_row, r ->> 'map'; end if; if length(coalesce(r ->> 'name', '')) > 40 then raise exception 'BAD_ROW: row % — name longer than 40 characters', v_row; end if; end loop; for r in select * from jsonb_array_elements(p_teams) loop v_arena := null; if coalesce(r ->> 'map', '') <> '' then select id into v_arena from arenas where event_id = v_ev and number::text = r ->> 'map'; end if; if v_arena is null then select arena_id into v_arena from teams where event_id = v_ev and number = (r ->> 'number')::int; end if; if v_arena is null then select a.id into v_arena from arenas a where a.event_id = v_ev and a.phase = 'lobby' and (select count(*) from teams t where t.arena_id = a.id) < v_size order by a.number limit 1; end if; if v_arena is null then raise exception 'ALL_MAPS_FULL'; end if; v_generated := coalesce(r ->> 'pin', '') = ''; v_pin := case when v_generated then _new_pin(_cfg(v_ev, 'pin_length')) else r ->> 'pin' end; v_salt := _new_token(); insert into teams(event_id, arena_id, number, name, pin_salt, pin_hash) values (v_ev, v_arena, (r ->> 'number')::int, nullif(trim(r ->> 'name'), ''), v_salt, _hash(v_salt || v_pin)) on conflict (event_id, number) do update set name = coalesce(nullif(trim(r ->> 'name'), ''), teams.name), pin_salt = excluded.pin_salt, pin_hash = excluded.pin_hash, arena_id = case when (select phase from arenas where id = teams.arena_id) = 'lobby' then excluded.arena_id else teams.arena_id end returning * into v_team; if not exists (select 1 from inventory where team_id = v_team.id) then perform _add_item(v_team.id, 'pistol', 1); perform _add_item(v_team.id, 'medkit', 1); end if; v_out := v_out || jsonb_build_object('number', v_team.number, 'name', v_team.name, 'map', (select number from arenas where id = v_team.arena_id), 'pin', case when v_generated then v_pin end); v_n := v_n + 1; end loop; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'import_teams', jsonb_build_object('count', v_n)); return jsonb_build_object('imported', v_n, 'squads', v_out); end $$; create or replace function host_roster(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; begin v_ev := _auth_host(p_token); return (select coalesce(jsonb_agg(jsonb_build_object('team_id', t.id, 'map', a.number, 'number', t.number, 'name', t.name, 'bus', t.bus, 'ready', t.ready, 'players', (select count(*) from players p where p.team_id = t.id and p.active)) order by a.number, t.number), '[]'::jsonb) from teams t join arenas a on a.id = t.arena_id where t.event_id = v_ev); end $$; create or replace function host_create_trial(p_code text, p_name text, p_secret text, p_arenas int default 1) returns jsonb language plpgsql security definer set search_path = public as $$ declare r jsonb; begin r := host_create_event(p_code, 'TRIAL · ' || coalesce(nullif(trim(p_name), ''), 'Rehearsal'), p_secret, p_arenas); update events set is_trial = true, settings = settings || jsonb_build_object( 'auto_pacing', 1, 'phase_schedule', '1,3,5,7', 'zone_warning', 30, 'shuttle_seconds', 12, 'roles_seconds', 12, 'recovery_seconds', 45, 'airdrop_interval', 2, 'intel_fallback', 45, 'attack_cooldown', 45, 'protect_seconds', 45, 'mission_time_pct', 70, 'airdrop_window', 90) where id = (r ->> 'event_id')::uuid; insert into audit_log(event_id, actor, action) values ((r ->> 'event_id')::uuid, 'host', 'create_trial'); return r || jsonb_build_object('trial', true); end $$; create or replace function host_trial_status(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; e events; begin v_ev := _auth_host(p_token); select * into e from events where id = v_ev; return jsonb_build_object( 'is_trial', e.is_trial, 'steps', jsonb_build_object( 'squads', exists (select 1 from teams where event_id = v_ev), 'joined', exists (select 1 from teams where event_id = v_ev and ready), 'boarding', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'shuttle.assigned'), 'shuttle', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'shuttle.departed'), 'roles', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'role.assignment.completed'), 'movement', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'squad.arrived'), 'mission', exists (select 1 from mission_instances mi join arenas a on a.id = mi.arena_id where a.event_id = v_ev and mi.status = 'solved' and mi.kind in ('mission', 'relay')), 'wrong_answer', exists (select 1 from submissions s join teams t on t.id = s.team_id where t.event_id = v_ev and not s.correct), 'phase2', exists (select 1 from arenas where event_id = v_ev and match_phase >= 2), 'battle', exists (select 1 from battles b join arenas a on a.id = b.arena_id where a.event_id = v_ev and b.status = 'resolved'), 'airdrop', exists (select 1 from airdrops d join arenas a on a.id = d.arena_id where a.event_id = v_ev and d.status = 'claimed'), 'zone', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'zone.collapsed'), 'recovery', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'recovery.started'), 'pause', exists (select 1 from audit_log where event_id = v_ev and action = 'resume' and ok), 'chat', exists (select 1 from chat_messages c join arenas a on a.id = c.arena_id where a.event_id = v_ev), 'finale', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'final.started'), 'finale_round', exists (select 1 from mission_instances mi join arenas a on a.id = mi.arena_id where a.event_id = v_ev and mi.sync_round_id is not null and mi.status = 'solved'), 'results', exists (select 1 from arenas where event_id = v_ev and results_locked), 'winner', exists (select 1 from arenas where event_id = v_ev and winner_revealed) )); end $$; create or replace function _host_exec_p0(p_ev uuid, p_arena uuid, p_cmd text, p_args jsonb, p_reason text) returns jsonb language plpgsql as $$ declare a arenas; e events; t teams; v_delta interval; v_pin text; v_salt text; v_out jsonb := '[]'::jsonb; i int; j int; v_tokens jsonb; v_num int; v_size int; v_count int; v_names text[] := array['Ava','Ben','Cleo','Dev','Esha','Finn','Gia','Hari','Ivy','Jai','Kai','Lia','Mo','Nia','Om','Pia']; begin select * into e from events where id = p_ev; if p_arena is not null then select * into a from arenas where id = p_arena; end if; if p_cmd in ('trial_skip', 'trial_bots', 'trial_reset') and not e.is_trial then raise exception 'TRIAL_ONLY'; end if; case p_cmd when 'set_phase', 'next_phase' then if a.phase <> 'play' then raise exception 'WRONG_PHASE'; end if; i := case when p_cmd = 'next_phase' then a.match_phase + 1 else (p_args ->> 'phase')::int end; if i is null or i < 0 or i > 4 then raise exception 'BAD_PHASE'; end if; perform _set_match_phase(a.id, i); perform _tick(a.id, true); return jsonb_build_object('phase', i); when 'hide_rankings' then update arenas set overlay = overlay || jsonb_build_object('hide_rankings', coalesce((p_args ->> 'on')::boolean, true)) where id = a.id; when 'reset_pin' then select * into t from teams where id = (p_args ->> 'team_id')::uuid and event_id = p_ev for update; if t.id is null then raise exception 'NOT_FOUND'; end if; v_pin := _new_pin(_cfg(p_ev, 'pin_length')); v_salt := _new_token(); update teams set pin_salt = v_salt, pin_hash = _hash(v_salt || v_pin) where id = t.id; delete from pin_failures where event_id = p_ev and team_number = t.number; return jsonb_build_object('number', t.number, 'name', t.name, 'pin', v_pin); when 'trial_skip' then if a.paused then raise exception 'PAUSED'; end if; v_count := greatest(1, least(600, coalesce((p_args ->> 'seconds')::int, 30))); perform _shift_arena(a.id, -_secs(v_count)); perform _tick(a.id, true); return jsonb_build_object('skipped', v_count); when 'trial_reset' then perform _host_exec(p_ev, a.id, 'reset_arena', '{"confirm":"RESET"}'::jsonb, p_reason); update arenas set match_phase = 0, phase_started_at = null, phase_next_at = null, zone_hold = false where id = a.id; when 'trial_bots' then if a.phase <> 'lobby' then raise exception 'WRONG_PHASE'; end if; v_size := _cfg(p_ev, 'arena_size'); v_count := greatest(1, least(coalesce((p_args ->> 'count')::int, 3), v_size - (select count(*) from teams where arena_id = a.id)::int)); if v_count < 1 or (select count(*) from teams where arena_id = a.id) >= v_size then raise exception 'ALL_MAPS_FULL'; end if; for i in 1..v_count loop select coalesce(max(number), 0) + 1 into v_num from teams where event_id = p_ev; v_pin := _new_pin(6); v_salt := _new_token(); insert into teams(event_id, arena_id, number, name, pin_salt, pin_hash) values (p_ev, a.id, v_num, 'Bot-' || lpad(v_num::text, 2, '0'), v_salt, _hash(v_salt || v_pin)) returning * into t; perform _add_item(t.id, 'pistol', 1); perform _add_item(t.id, 'medkit', 1); v_tokens := '[]'::jsonb; for j in 1..4 loop v_tokens := v_tokens || to_jsonb((join_team(e.code, v_num, v_pin, v_names[1 + ((v_num * 4 + j) % 16)] || ' ' || j, true, true, null)) ->> 'token'); end loop; v_out := v_out || jsonb_build_object('team_id', t.id, 'number', v_num, 'tokens', v_tokens); end loop; return jsonb_build_object('bots', v_out); else raise exception 'UNKNOWN_COMMAND'; end case; return '{}'::jsonb; end $$; create or replace function host_command(p_token text, p_arena uuid, p_cmd text, p_args jsonb default '{}'::jsonb, p_reason text default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_ids uuid[]; v_id uuid; v_out jsonb := '{}'::jsonb; v_err text; v_res jsonb; v_delta interval; v_logargs jsonb; v_all_ok text[] := array['open_boarding','assign_buses','drive','finalize_roles','pause','resume','broadcast','clear_overlay', 'blackout','countdown','story','bargain','zone_warn','zone_now','zone_cancel','zone_set','spawn_airdrop','begin_finale', 'finale_stage','launch_sync','close_sync','lock_results','reveal_winner','end_game','reveal_squad00', 'next_phase','set_phase','hide_rankings','trial_skip','trial_reset']; v_new text[] := array['set_phase','next_phase','hide_rankings','reset_pin','trial_skip','trial_bots','trial_reset']; begin v_ev := _auth_host(p_token); p_args := coalesce(p_args, '{}'::jsonb); v_logargs := p_args - 'pin'; if p_arena is null then if p_cmd = any(v_all_ok) then select array_agg(id order by number) into v_ids from arenas where event_id = v_ev; else v_ids := array[null::uuid]; end if; else if not exists (select 1 from arenas where id = p_arena and event_id = v_ev) then raise exception 'BAD_ARENA'; end if; v_ids := array[p_arena]; end if; foreach v_id in array v_ids loop begin v_delta := null; if p_cmd = 'resume' then select now() - paused_at into v_delta from arenas where id = v_id and paused; end if; if p_cmd = any(v_new) then v_res := _host_exec_p0(v_ev, v_id, p_cmd, p_args, p_reason); elsif p_cmd = 'clear_overlay' then update arenas set overlay = (select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) from jsonb_each(overlay) as x(k, v) where k in ('match', 'trial')) where id = v_id; v_res := '{}'::jsonb; else v_res := _host_exec(v_ev, v_id, p_cmd, p_args, p_reason); end if; if p_cmd = 'resume' and v_delta is not null then update arenas set phase_next_at = phase_next_at + v_delta, phase_started_at = phase_started_at + v_delta, shuttle_departed_at = shuttle_departed_at + v_delta, overlay = case when overlay ? 'match' and overlay #>> '{match,next_at}' is not null then jsonb_set(overlay, '{match,next_at}', to_jsonb((overlay #>> '{match,next_at}')::timestamptz + v_delta)) else overlay end where id = v_id; elsif p_cmd = 'begin_finale' then update arenas set match_phase = 5, phase_started_at = now(), phase_next_at = null, overlay = overlay || jsonb_build_object('match', jsonb_build_object('phase', 5, 'started_at', now(), 'next_at', null, 'zone_target', 5)) where id = v_id; perform _feed(v_id, 'phase.started', jsonb_build_object('phase', 5)); elsif p_cmd = 'zone_cancel' then update arenas set zone_hold = true where id = v_id; elsif p_cmd in ('zone_warn', 'zone_now', 'zone_set') then update arenas set zone_hold = false where id = v_id; elsif p_cmd = 'reset_arena' then update arenas set match_phase = 0, phase_started_at = null, phase_next_at = null, zone_hold = false where id = v_id; end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), v_res); insert into audit_log(event_id, arena_id, actor, action, args, reason) values (v_ev, v_id, 'host', p_cmd, v_logargs, p_reason); exception when others then v_err := sqlerrm; insert into audit_log(event_id, arena_id, actor, action, args, reason, ok, error) values (v_ev, v_id, 'host', p_cmd, v_logargs, p_reason, false, v_err); if array_length(v_ids, 1) = 1 then return jsonb_build_object('ok', false, 'error', v_err); end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), jsonb_build_object('error', v_err)); end; if v_id is not null then perform _ping_arena(v_id, 'host'); end if; end loop; return jsonb_build_object('ok', true, 'result', v_out); end $$; update arenas a set overlay = a.overlay || jsonb_build_object('match', jsonb_build_object('phase', a.match_phase, 'started_at', a.phase_started_at, 'next_at', a.phase_next_at, 'duel_phase', 2, 'zone_target', _phase_zone_target(a.match_phase))) where a.phase in ('play', 'finale') and not (a.overlay ? 'match'); update teams t set bus = s.bus from ( select id, 1 + ((row_number() over (partition by arena_id order by number)) - 1)::int / 3 as bus from teams ) s where t.id = s.id and t.bus is null; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'host_create_trial', 'host_trial_status']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$;
